ruleHooks.extraMethods:
; Obter Próximo Código da Embalagem (não reaproveita)
;
; set sc=$$ObterProximaEmbalagem^WDOMTESTEROM005RG(codEmpresa,.codEmbalagem)
ObterProximaEmbalagem(codEmpresa,codEmbalagem)	;
$$$VAR
;
set codEmbalagem=$increment(^WDOMTESTEROMTAB(1,codEmpresa,0))
;
quit $$$OK
;
; Obter Tabela de Embalagens (F7 de cadastrados)
;
; set sc=$$ObterTabEmbalagem^WDOMTESTEROM005RG(codEmpresa,.tabEmbalagem)
ObterTabEmbalagem(codEmpresa,tabEmbalagem)	;
$$$VAR
new codEmbalagem,dados
;
kill tabEmbalagem
set codEmbalagem=""
for  set codEmbalagem=$order(^WDOMTESTEROMTAB(1,codEmpresa,1,codEmbalagem)) quit:codEmbalagem=""  do
. set dados=$get(^WDOMTESTEROMTAB(1,codEmpresa,1,codEmbalagem))
. set tabEmbalagem(codEmbalagem)=$piece(dados,Z,3)_Z_$piece(dados,Z,4)
;
quit $$$OK
;
; Ver Embalagem (descrição^peso^altura^largura^profundidade)
;
; set sc=$$VerEmbalagem^WDOMTESTEROM005RG(codEmpresa,codEmbalagem,.embalagem)
VerEmbalagem(codEmpresa,codEmbalagem,embalagem)	;
$$$VAR
new dados
;
set embalagem=""
if $get(codEmbalagem)="" quit $$$ERROR(10000,"Embalagem: Campo obrigatório!")
if '$data(^WDOMTESTEROMTAB(1,codEmpresa,1,codEmbalagem)) quit $$$ERROR(10000,"Embalagem "_codEmbalagem_" não cadastrada!")
;
set dados=$get(^WDOMTESTEROMTAB(1,codEmpresa,1,codEmbalagem))
set embalagem=$piece(dados,Z,3,7)
;
quit $$$OK
